INSERT INTO `payment_concept` VALUES 
  (1,@Domain,'ECEMP','PREST. IT A CARGO DE LA EMPRESA',7,1,'DIAS_ENFERMEDAD_COMUN_4_15 * BASE_REGULADORA * 0.60','ECEMP','( COTIZACION_IT == \"MENSUAL\" ? 30 - ( DIAS_MES - DIAS_ENFERMEDAD_COMUN) : DIAS_ENFERMEDAD_COMUN ) * BASE_REGULADORA'),
  (2,@Domain,'ECSS','PREST. IT A CARGO DEL INSS',7,1,'DIAS_ENFERMEDAD_COMUN_16_20 * BASE_REGULADORA * 0.60 + DIAS_ENFERMEDAD_COMUN_21 * BASE_REGULADORA * 0.75','ECSS',NULL),
  (3,@Domain,'MTNAD','PREST. MATERNIDAD Y/O R.E',7,1,'0','0','( COTIZACION_IT == \"MENSUAL\" ? 30 - ( DIAS_MES - DIAS_MATERNIDAD) : DIAS_MATERNIDAD ) * BASE_REGULADORA'),
  (4,@Domain,'ATEP','PREST. A.T. y E.P. ',7,1,'DIAS_ENFERMEDAD_PROFESIONAL * BASE_REGULADORA * 0.75','ATEP','( COTIZACION_IT == \"MENSUAL\" ? 30 - ( DIAS_MES - DIAS_ENFERMEDAD_PROFESIONAL) : DIAS_ENFERMEDAD_PROFESIONAL ) * BASE_REGULADORA'),
  (5,@Domain,'GTZDO','GARANTIZADO EMPRESA SITUACION I.T.',1,1,'GARANTIZADO*DIAS_GARANTIZADOS/DIAS_MES>TOTAL_PRESTACIONES_IT?GARANTIZADO*DIAS_GARANTIZADOS/DIAS_MES-TOTAL_PRESTACIONES_IT:0.00','GTZDO',NULL),
  (6,@Domain,'FIVAC','Vacaciones no disfrutadas',1,1,'DIAS_VACACIONES_NO_DISFRUTADAS * IMPORTE_DIA_VACACIONES','FIVAC','FIVAC'),
  (7,@Domain,'INDEM','Indemnización',6,1,'IMPORTE_INDEMNIZACION','0.00','0.00');

