INSERT INTO `system_cost` VALUES 
  (1,@Domain,'2010-01-01',NULL,'23.60 %','( BASE_CGC_E=( BASE_CGC + ( isdef BASE_MTNAD ? BASE_MTNAD : 0.00 ) ) ) * 23.60/100',0,'CGC_E'),
  (2,@Domain,'2010-01-01',NULL,'12.00 %','BASE_ESTR * 12.00/100',4,'EXTR_E'),
  (3,@Domain,'2010-01-01',NULL,'23.60 %','BASE_NESTR * 23.60/100',5,'NEXTR_E'),
  (4,@Domain,'2010-01-01',NULL,'@{PORCENTAJE_IT} %','( BASE_CGP_E=( BASE_CGP + ( isdef BASE_MTNAD ? BASE_MTNAD : 0.00 ) ) ) * (PORCENTAJE_IT=( isdef OCUPACION ? OCUPACION_IT[OCUPACION] : TARIFA_IT))/100',1,'IT_E'),
  (5,@Domain,'2010-01-01',NULL,'@{PORCENTAJE_IMS} %','BASE_CGP_E * (PORCENTAJE_IMS=( isdef OCUPACION ? OCUPACION_IMS[OCUPACION] : TARIFA_IMS))/100',1,'IMS_E'),
  (6,@Domain,'2010-01-01',NULL,'@{PORCENTAJE_DESMPL_E} %','BASE_CGP_E * (PORCENTAJE_DESMPL_E=(INDEFINIDO ? 5.50 : (TIEMPO_COMPLETO ? 6.70 : 7.70)))/100',2,'DESMPL_E'),
  (7,@Domain,'2010-01-01',NULL,'0.20 %','BASE_CGP_E * 0.20/100',10,'FOGASA_E'),
  (8,@Domain,'2010-01-01',NULL,'0.60 %','BASE_CGP_E * 0.60/100',3,'FP_E'),
  (9,@Domain,'2010-01-01',NULL,'36.00 %','CONTRATO_CORTA_DURACION ? ( CGC_E * 36.00 / 100 ) : 0.00',0,'CGC_E_TEMP'),
